/**
 * @suppress
 */
public object FfiConverterTypeFfiSession: FfiConverter<FfiSession, Long> {
    override fun lower(value: FfiSession): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): FfiSession {
        return FfiSession(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): FfiSession {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: FfiSession) = 8UL

    override fun write(value: FfiSession, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



