/**
 * Every failure, as the short code of crypto spec §11 (`unlock_failed`, `weak_password`, …).
 * The code never contains a secret.
 */
sealed class FfiException: kotlin.Exception() {
    
    class Failed(
        
        val `code`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "code=${ `code` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        

        return when(buf.getInt()) {
            1 -> FfiException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiException): ULong {
        return when(value) {
            is FfiException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
            )
        }
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.Failed -> {
                buf.putInt(1)
                FfiConverterString.write(value.`code`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




enum class FfiKeyLevel {
    
    SOFTWARE,
    TEE,
    STRONG_BOX;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeFfiKeyLevel: FfiConverterRustBuffer<FfiKeyLevel> {
    override fun read(buf: ByteBuffer) = try {
        FfiKeyLevel.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: FfiKeyLevel) = 4UL

    override fun write(value: FfiKeyLevel, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





sealed class FfiScope {
    
    object All : FfiScope()
    
    
    object Unassigned : FfiScope()
    
    
    data class Bank(
        val `bankId`: kotlin.String) : FfiScope()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiScope : FfiConverterRustBuffer<FfiScope>{
    override fun read(buf: ByteBuffer): FfiScope {
        return when(buf.getInt()) {
            1 -> FfiScope.All
            2 -> FfiScope.Unassigned
            3 -> FfiScope.Bank(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiScope): ULong = when(value) {
        is FfiScope.All -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
